#!/usr/bin/env bash
set -eEuo pipefail
# isolated-initializations: v1
JOB_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
source "${EXP:-/workspace/dgs_exp}/runpod/env.sh"
export AABB_CONFIG="$JOB_DIR/aabb.json"
export N_FRAMES=300
cd "$EXP"
# settings_sha256: d0ab6c1ecaa76010f68cfc9d8d14882511013f3e10d10d4d9ccf2fc682821821
CURRENT_RUN=""
on_failure() {
  local code=$?
  if [ -n "$CURRENT_RUN" ]; then
    python "$EXP/scripts/19_execution_status.py" record --run-dir "$RUNS/stream/$CURRENT_RUN" --stage initialization --state failed --exit-code "$code" || true
  fi
  exit "$code"
}
# per-condition failures are handled by run_condition below
conda activate gs
python "$EXP/scripts/16_snapshot_environment.py" --out "$JOB_DIR/environment_gs.json" --lock-out "$JOB_DIR/versions.lock.json"
conda activate da3
python "$EXP/scripts/16_snapshot_environment.py" --out "$JOB_DIR/environment_da3.json"
conda activate gs

INIT_OK=0
INIT_FAILED=0
FAIL_LOG="$JOB_DIR/initialization_failures.tsv"
printf 'run\tstate\texit_code\talignment_report\n' > "$FAIL_LOG"
run_condition() {
  local name=$1 func=$2 alignment=${3:-} code state
  set +e
  ( set -eEuo pipefail; trap 'exit $?' ERR; "$func" )
  code=$?
  set -e
  if [ "$code" -eq 0 ]; then
    INIT_OK=$((INIT_OK + 1))
    return 0
  fi
  state=failed
  if [ -n "$alignment" ] && [ -f "$alignment" ] && \
     python -c 'import json,sys; sys.exit(0 if json.load(open(sys.argv[1])).get("alignment_pass") is False else 1)' "$alignment"; then
    state=alignment_failed
  fi
  python "$EXP/scripts/19_execution_status.py" record --run-dir "$RUNS/stream/$name" \
    --stage initialization --state "$state" --exit-code "$code" || true
  printf '%s\t%s\t%s\t%s\n' "$name" "$state" "$code" "$alignment" >> "$FAIL_LOG"
  INIT_FAILED=$((INIT_FAILED + 1))
  echo "INIT_SKIPPED: $name ($state, exit $code); continuing with the next condition."
}

